python3 - <<'PY'
import openpyxl
from openpyxl.utils import get_column_letter

wb = openpyxl.load_workbook('/root/mill_demand_sheet.xlsx', data_only=True)
ws = wb['Mill']

needle = 'CNC'
found = []
for row in ws.iter_rows():
    for cell in row:
        v = cell.value
        if v is None:
            continue
        s = str(v)
        if 'CNC' in s and 'Demand' in s and 'Mill' in s:
            found.append((cell.row, cell.column, s))

print('Matches:', len(found))
for r,c,s in found[:20]:
    print(f"{get_column_letter(c)}{r}: {s}")

# if none, broaden search for 'Demand' and 'Mill'
if not found:
    found2=[]
    for row in ws.iter_rows():
        for cell in row:
            v=cell.value
            if v is None:
                continue
            s=str(v)
            if 'Demand' in s and 'Mill' in s:
                found2.append((cell.row, cell.column, s))
    print('Broader matches (Demand & Mill):', len(found2))
    for r,c,s in found2[:30]:
        print(f"{get_column_letter(c)}{r}: {s}")

# print sheet dimensions and first 20 rows col A-C for clues
print('max_row', ws.max_row, 'max_col', ws.max_column)
for r in range(1, min(21, ws.max_row+1)):
    a=ws.cell(row=r, column=1).value
    b=ws.cell(row=r, column=2).value
    c=ws.cell(row=r, column=3).value
    if any(v is not None for v in (a,b,c)):
        print(r, a, b, c)
